jedi.inference.cache.inference_state_met:
@wraps(function)
def wrapper(obj, *args, **kwargs):
    cache = obj.inference_state.memoize_cache
    try:
        memo = cache[function]
    except KeyError:
        cache[function] = memo = {}
    key = (obj, args, frozenset(kwargs.items()))
    if key in memo:
        (actual_generator, cached_lst) = memo[key]
    else:
        actual_generator = function(obj, *args, **kwargs)
        cached_lst = []
        memo[key] = (actual_generator, cached_lst)
    i = 0
    while True:
        try:
            next_element = cached_lst[i]
            if next_element is _RECURSION_SENTINEL:
                debug.warning('Found a generator recursion for %s' % obj)
                return
        except IndexError:
            cached_lst.append(_RECURSION_SENTINEL)
            next_element = next(actual_generator, None)
            if next_element is None:
                cached_lst.pop()
                return
            cached_lst[-1] = next_element
        yield next_element
        i += 1

jedi.cache.time_cache.decorator.wrapper:
@wraps(func)
def wrapper(*args, **kwargs):
    key = (args, frozenset(kwargs.items()))
    try:
        (created, result) = cache[key]
        if time.time() < created + seconds:
            return result
    except KeyError:
        pass
    result = func(*args, **kwargs)
    cache[key] = (time.time(), result)
    return result

jedi.api.refactoring.__init__.rename:
def rename(inference_state, definitions, new_name):
    file_renames = set()
    file_tree_name_map = {}
    if not definitions:
        raise RefactoringError('There is no name under the cursor')
    for d in definitions:
        tree_name = d._name.tree_name
        if (d.type == 'module' and tree_name is None and d.module_path is not None):
            p = Path(d.module_path)
            file_renames.add(_calculate_rename(p, new_name))
        elif isinstance(d._name, ImplicitNSName):
            for p in d._name._value.py__path__():
                file_renames.add(_calculate_rename(Path(p), new_name))
        elif tree_name is not None:
            fmap = file_tree_name_map.setdefault(d.module_path, {})
            fmap[tree_name] = tree_name.prefix + new_name
    return Refactoring(inference_state, file_tree_name_map, file_renames)

jedi.plugins.pytest.infer_anonymous_para:
def infer_anonymous_param(func):

    def get_returns(value):
        if value.tree_node.annotation is not None:
            result = value.execute_with_values()
            if any((v.name.get_qualified_names(include_module_names=True) == ('typing', 'Generator') for v in result)):
                return ValueSet.from_sets((v.py__getattribute__('__next__').execute_annotation() for v in result))
            return result
        function_context = value.as_context()
        if function_context.is_generator():
            return function_context.merge_yield_values()
        else:
            return function_context.get_return_values()

    def wrapper(param_name):
        if param_name.annotation_node:
            return func(param_name)
        (is_pytest_param, param_name_is_function_name) = _is_a_pytest_param_and_inherited(param_name)
        if is_pytest_param:
            module = param_name.get_root_context()
            fixtures = _goto_pytest_fixture(module, param_name.string_name, skip_own_module=param_name_is_function_name)
            if fixtures:
                return ValueSet.from_sets((get_returns(value) for fixture in fixtures for value in fixture.infer()))
        return func(param_name)
    return wrapper

jedi.__main__._complete:
def _complete():
    import jedi
    import pdb
    if '-d' in sys.argv:
        sys.argv.remove('-d')
        jedi.set_debug_function()
    try:
        completions = jedi.Script(sys.argv[2]).complete()
        for c in completions:
            c.docstring()
            c.type
    except Exception as e:
        print(repr(e))
        pdb.post_mortem()
    else:
        print(completions)
